test("on time work keeps its raw score and has zero late periods", function () {
  assert.deepEqual(code.applyLatePenalty({maxPoints: 50, rawScore: 45, deadline: 1704067200000, submittedAt: 1704067200000}), {periodsLate: 0, deduction: 0, score: 45});
  assert.equal(code.countLatePeriods({deadline: 1704067200000, submittedAt: 1704067200000}), 0);
});

test("work submitted one millisecond before the deadline is not penalised", function () {
  assert.deepEqual(code.applyLatePenalty({maxPoints: 50, rawScore: 45, deadline: 1704067200000, submittedAt: 1704067199999}), {periodsLate: 0, deduction: 0, score: 45});
  assert.equal(code.countLatePeriods({deadline: 1704067200000, submittedAt: 1704067199999}), 0);
});

test("one millisecond late starts one period and deducts ten percent of the maximum", function () {
  assert.deepEqual(code.applyLatePenalty({maxPoints: 100, rawScore: 45, deadline: 1704067200000, submittedAt: 1704067200001}), {periodsLate: 1, deduction: 10, score: 35});
  assert.equal(code.countLatePeriods({deadline: 1704067200000, submittedAt: 1704067200001}), 1);
});

test("one hour late deducts five from a fifty point maximum and scores forty", function () {
  assert.deepEqual(code.applyLatePenalty({maxPoints: 50, rawScore: 45, deadline: 1704067200000, submittedAt: 1704070800000}), {periodsLate: 1, deduction: 5, score: 40});
  assert.equal(code.countLatePeriods({deadline: 1704067200000, submittedAt: 1704070800000}), 1);
});

test("two hours late across midnight is one period not two calendar days", function () {
  assert.deepEqual(code.applyLatePenalty({maxPoints: 50, rawScore: 45, deadline: 1704063600000, submittedAt: 1704070800000}), {periodsLate: 1, deduction: 5, score: 40});
  assert.equal(code.countLatePeriods({deadline: 1704063600000, submittedAt: 1704070800000}), 1);
});

test("exactly twenty four hours late does not start a second period", function () {
  assert.deepEqual(code.applyLatePenalty({maxPoints: 50, rawScore: 45, deadline: 1709164800000, submittedAt: 1709251200000}), {periodsLate: 1, deduction: 5, score: 40});
  assert.equal(code.countLatePeriods({deadline: 1709164800000, submittedAt: 1709251200000}), 1);
});

test("twenty four hours plus one millisecond starts a second period", function () {
  assert.deepEqual(code.applyLatePenalty({maxPoints: 50, rawScore: 45, deadline: 1709164800000, submittedAt: 1709251200001}), {periodsLate: 2, deduction: 10, score: 35});
  assert.equal(code.countLatePeriods({deadline: 1709164800000, submittedAt: 1709251200001}), 2);
});

test("forty nine hours late is three periods and scores thirty", function () {
  assert.deepEqual(code.applyLatePenalty({maxPoints: 50, rawScore: 45, deadline: 1706662800000, submittedAt: 1706839200000}), {periodsLate: 3, deduction: 15, score: 30});
  assert.equal(code.countLatePeriods({deadline: 1706662800000, submittedAt: 1706839200000}), 3);
});

test("exactly seventy two hours late stays at three periods", function () {
  assert.deepEqual(code.applyLatePenalty({maxPoints: 50, rawScore: 45, deadline: 1704067200000, submittedAt: 1704326400000}), {periodsLate: 3, deduction: 15, score: 30});
  assert.equal(code.countLatePeriods({deadline: 1704067200000, submittedAt: 1704326400000}), 3);
});

test("exactly one hundred twenty hours late is five periods and scores twenty", function () {
  assert.deepEqual(code.applyLatePenalty({maxPoints: 50, rawScore: 45, deadline: 1704067200000, submittedAt: 1704499200000}), {periodsLate: 5, deduction: 25, score: 20});
  assert.equal(code.countLatePeriods({deadline: 1704067200000, submittedAt: 1704499200000}), 5);
});

test("more than five periods late scores zero while still counting six periods", function () {
  var result = code.applyLatePenalty({maxPoints: 50, rawScore: 45, deadline: 1704067200000, submittedAt: 1704499260000});
  assert.equal(result.periodsLate, 6);
  assert.equal(result.score, 0);
  assert.equal(code.countLatePeriods({deadline: 1704067200000, submittedAt: 1704499260000}), 6);
});

test("a raw score below the one period deduction is clamped to zero", function () {
  assert.deepEqual(code.applyLatePenalty({maxPoints: 50, rawScore: 4, deadline: 1704067200000, submittedAt: 1704070800000}), {periodsLate: 1, deduction: 5, score: 0});
  assert.equal(code.countLatePeriods({deadline: 1704067200000, submittedAt: 1704070800000}), 1);
});

test("a raw score equal to the deduction scores exactly zero", function () {
  assert.deepEqual(code.applyLatePenalty({maxPoints: 50, rawScore: 5, deadline: 1704067200000, submittedAt: 1704070800000}), {periodsLate: 1, deduction: 5, score: 0});
  assert.equal(code.countLatePeriods({deadline: 1704067200000, submittedAt: 1704070800000}), 1);
});

test("three periods late clamps a raw score of ten down to zero", function () {
  assert.deepEqual(code.applyLatePenalty({maxPoints: 50, rawScore: 10, deadline: 1704067200000, submittedAt: 1704243600000}), {periodsLate: 3, deduction: 15, score: 0});
  assert.equal(code.countLatePeriods({deadline: 1704067200000, submittedAt: 1704243600000}), 3);
});

test("a raw score one point above the deduction scores one", function () {
  assert.deepEqual(code.applyLatePenalty({maxPoints: 50, rawScore: 6, deadline: 1704067200000, submittedAt: 1704070800000}), {periodsLate: 1, deduction: 5, score: 1});
  assert.equal(code.countLatePeriods({deadline: 1704067200000, submittedAt: 1704070800000}), 1);
});

test("an unknown comment field makes both functions throw unknown field comment", function () {
  assert.throws(function () {
    code.applyLatePenalty({maxPoints: 50, rawScore: 45, deadline: 1704067200000, submittedAt: 1704067200000, comment: "x"});
  }, /unknown field: comment/);
  assert.throws(function () {
    code.countLatePeriods({deadline: 1704067200000, submittedAt: 1704067200000, comment: "x"});
  }, /unknown field: comment/);
});
